async function loadSubstation33kv() {
  for(const entry of [registry.supplemental_assets?.wider_sub_coverage,registry.supplemental_assets?.grid_actions_inline].filter(Boolean)) {
    try {
      runtimeEvidence.substationRequests += 1;
      const payload=await fetchImmutable(entry.payload.path);
      invariant(payload.schema===entry.payload.schema && payload.generation===entry.generation,'sub coverage identity mismatch');
      invariant(payload.substation && typeof payload.substation==='object' && !Array.isArray(payload.substation),'sub coverage index missing');
      substation=payload.substation;
      runtimeEvidence.substationReady=true;
      runtimeEvidence.subCoverageSource=entry.generation;
      return;
    } catch(error) { runtimeEvidence.subCoverageFallback=true; }
  }
  substation=null;
}
